#include <stdint.h>

extern int DeliverEvent(uint32_t event_class, uint32_t event_spec);
extern int fmv_file_open(const char *path);
extern void fmv_print(const char *format, ...);
extern void fmv_shared_init(void *buffer, uint32_t size);
extern int CdControl(uint32_t command, void *parameter, void *result);
extern int CdRead2(uint32_t mode);

#define FMV_CD_EVENT_CLASS 0xF0000003u
#define FMV_CD_EVENT_SPEC  0x00008000u
#define FMV_FILE_ERROR     (-1)
#define FMV_DECODE_POLL_BUDGET 0x00800000u

struct fmv_rect_s16 {
    int16_t x;
    int16_t y;
    int16_t w;
    int16_t h;
};

struct fmv_rect_handoff {
    void *decode_blocks[2];           /* +0x00, +0x04 */
    uint32_t active_decode_index;     /* +0x08 */
    void *presentation_block;         /* +0x0C */
    struct fmv_rect_s16 rect_bank[2]; /* +0x10..+0x1F */
    uint32_t active_rect_index;       /* +0x20; domain {0,1} */
    struct fmv_rect_s16 present_rect; /* +0x24..+0x2B */
    uint32_t rect_ready;              /* +0x2C; domain {0,1} */
};

/*
 * Resident cd_subsystem_init registers class F0000003/spec 8000 with callback
 * 80045D5C. The callback publishes one at 80082484. An exhaustive resident
 * direct-JAL census of DeliverEvent at 8006C3AC finds only these disjoint
 * producers:
 *
 *   SPU F0000009/20
 *   libcd F0000003/20
 *   libcd F0000003/40
 *   libcd F0000003/40
 *
 * Therefore none is the registered FMV-event producer. getintr has no direct
 * DeliverEvent call either. The exact producer remains behind the BIOS or
 * interrupt-service boundary; these static facts do not establish delivery
 * frequency or promote the native event lifecycle.
 */
static void reviewed_resident_deliver_event_surface(void)
{
    DeliverEvent(0xF0000009u, 0x20u);
    DeliverEvent(FMV_CD_EVENT_CLASS, 0x20u);
    DeliverEvent(FMV_CD_EVENT_CLASS, 0x40u);
    DeliverEvent(FMV_CD_EVENT_CLASS, 0x40u);
}

/*
 * The player calls the 16-slot file helper at 800B6DD8. Both helper failures
 * return -1; 800B6DE8 then selects the failure diagnostic at 800B6E54. The
 * failure target rejoins shared initialization at 800B6E60/800B6E68. The
 * static route does not reveal the visible or eventual runtime outcome.
 */
static void file_open_frontier(const char *path, void *buffer)
{
    int handle = fmv_file_open(path);

    if (handle == FMV_FILE_ERROR)
        fmv_print("File not found");
    fmv_shared_init(buffer, 0x28000u);
}

/*
 * The player has exactly one direct call to this helper, at 0x800B72A0.
 * Its a0 is the 0x800CABE0 record whose base was materialized at 0x800B709C,
 * preserved in s3 at 0x800B70D4, and moved into a0 at 0x800B729C.
 *
 * The helper checks rect_ready once at entry.  While it remains zero, the
 * stack-local 0x00800000 budget is decremented before its zero test and the
 * ready field is polled again.  Exhaustion prints the diagnostic, publishes
 * rect_ready=1, normalizes active_rect_index to (old == 0), and copies the
 * selected 8-byte RECT slot's raw 16-bit x/y coordinates to present_rect.
 * The width/height fields are not written here.  Native-ready, already-ready,
 * and synthesized-timeout paths all converge on the sole rect_ready=0 store
 * before the conventional return.
 *
 * This closes the static recovery transition and pointer/field ownership.  It
 * does not establish a natural timeout, its frequency, malformed-media
 * policy, CD retry behavior, or a user-visible result.
 */
static void decode_timeout_frontier(
    volatile struct fmv_rect_handoff *record)
{
    uint32_t budget = FMV_DECODE_POLL_BUDGET;

    if (record->rect_ready == 0) {
        do {
            --budget;
            if (budget == 0) {
                fmv_print("Dec timeout");
                record->rect_ready = 1;
                record->active_rect_index =
                    (record->active_rect_index == 0);
                record->present_rect.x =
                    record->rect_bank[record->active_rect_index].x;
                record->present_rect.y =
                    record->rect_bank[record->active_rect_index].y;
            }
        } while (record->rect_ready == 0);
    }
    record->rect_ready = 0;
}

/*
 * Stream submission has two unbounded native retry loops: GetlocP retries at
 * 800B7044 until CdControl returns nonzero and CdRead2 retries at 800B7054.
 * Demute follows only after both submissions succeed. Native retry counts,
 * device-error policy and user-visible outcomes remain lifecycle debt.
 */
static void cd_submit_retry_frontier(void *location)
{
    while (!CdControl(0x15u, location, 0)) {
    }
    while (!CdRead2(0x1C0u)) {
    }
    CdControl(0x0Cu, 0, 0);
}

